trigger.body:
/************************************************************************* * Keeps A_AMORTIZATION.TOTALAMOUNT in sync with the sum of its lines. * Fires after any insert, update or delete on A_AMORTIZATIONLINE so that * the header total is always accurate — even when lines are edited on a * reactivated document without going through the confirm process. * * Uses the parent id from :new (insert/update) or :old (delete). ************************************************************************/
BEGIN
IF AD_isTriggerEnabled()='N' THEN RETURN; END IF;
IF (INSERTING OR UPDATING) THEN UPDATE A_AMORTIZATION SET TOTALAMORTIZATION = ( SELECT COALESCE(SUM(AMORTIZATIONAMT), 0) FROM A_AMORTIZATIONLINE WHERE A_AMORTIZATION_ID = :new.A_AMORTIZATION_ID ) WHERE A_AMORTIZATION_ID = :new.A_AMORTIZATION_ID; END IF;
IF (DELETING) THEN UPDATE A_AMORTIZATION SET TOTALAMORTIZATION = ( SELECT COALESCE(SUM(AMORTIZATIONAMT), 0) FROM A_AMORTIZATIONLINE WHERE A_AMORTIZATION_ID = :old.A_AMORTIZATION_ID ) WHERE A_AMORTIZATION_ID = :old.A_AMORTIZATION_ID; END IF;
END ETGO_A_AMORTLINE_TOTAL_TRG
